#!/usr/bin/env bash
set -Eeuo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)";cd "$ROOT"
find scripts tests src -type f \( -name '*.pyc' -o -name '*.pyo' \) -delete 2>/dev/null||true;find scripts tests src -type d -name __pycache__ -prune -exec rm -rf {} + 2>/dev/null||true;rm -rf .pytest_cache tests/.pytest_cache
STAGE=(config/practical_architecture_mapping_v1.json source_inputs/practical_architecture_mapping_v1 src/fr3_cbf/practical_architecture_mapping.py scripts/44_0_run_practical_architecture_mapping.py scripts/44_1_validate_practical_architecture_mapping.py scripts/44_2_build_phase1_campaign_candidate.py scripts/44_3_sync_practical_architecture_status.py scripts/44_4_build_practical_architecture_review_bundle.py tests/test_practical_architecture_mapping.py docs/PRACTICAL_64T64R_ARCHITECTURE_MAPPING.md docs/PHASE1_CAMPAIGN_REVIEW_PROTOCOL.md wrappers/practical_architecture RUN_PRACTICAL_ARCHITECTURE_PHASE1_PREP_DROPIN.sh README_PRACTICAL_ARCHITECTURE_PHASE1_PREP.md PRACTICAL_ARCHITECTURE_PHASE1_PREP_MANIFEST.sha256 PRACTICAL_ARCHITECTURE_PHASE1_PREP_TEST_REPORT.txt PROJECT_STATUS.md NEXT_IMMEDIATE_STEP.md evidence/practical_architecture_mapping_v1 campaign/phase1_candidate_v1)
git add -- "${STAGE[@]}";git diff --cached --check;sha256sum -c evidence/practical_architecture_mapping_v1/EVIDENCE_MANIFEST.sha256;git commit -m 'Map generic 64T64R architecture and freeze phase1 review candidate';git push
COMMIT="$(git rev-parse HEAD)";REVIEW="evidence/practical_architecture_mapping_v1/FR3_PRACTICAL_ARCHITECTURE_PHASE1_REVIEW_v1.zip";echo 'PRACTICAL ARCHITECTURE PUSH: PASS';echo "Commit: $COMMIT";echo "Review bundle: $ROOT/$REVIEW";echo "Review bundle SHA-256: $(sha256sum "$REVIEW"|awk '{print $1}')";echo 'Campaign execution authorized: NO';echo 'Next gate: ACQUIRE_FOUR_ADDITIONAL_PROTECTED_PASS_RECORDS_AND_INDEPENDENTLY_REVIEW_PHASE1_CAMPAIGN_CANDIDATE'
